ion":"1-indexed line the finding anchors to","type":"integer","minimum":-9007199254740991,"maximum":9007199254740991},"summary":{"description":"One-sentence statement of the defect","type":"string"},"short_summary":{"description":"Compressed label for compact UI (≤60 chars): the claim alone, no rationale or consequence clause","type":"string","maxLength":60},"failure_scenario":{"description":"Concrete inputs/state → wrong output/crash","type":"string"},"category":{"description":"Short kebab-case slug of the finding type, e.g. "correctness", "simplification", "efficiency", "test-coverage"","type":"string","maxLength":40},"verdict":{"description":"Set when a verify pass ran; absent on inline-only reviews","type":"string","enum":["CONFIRMED","PLAUSIBLE"]},"outcome":{"description":"Set ONLY when re-reporting after applying fixes: what happened to this finding","type":"string","enum":["fixed","skipped","no_change_needed"]}},"required":["file","summary","failure_scenario"],"additionalProperties":false}}},"required":["findings"],"additionalProperties":false}},{"name":"SendMessage","description":"# SendMessage

